            }
        }
    };

    std::vector<int> predecessor;
    std::size_t cycle_budget = graph.size();
    unsigned cycle_checks = 0;
    if constexpr (Track) predecessor.assign(graph.size(), -1);
    const auto detect_cycles = [&]() {
        for (auto& bits : state) bits &= std::uint8_t{7};
        for (int root = 0; root < n; ++root) {
