#include SIRKIT_TEST_NEGATIVE_PATH_SOURCE
#include <algorithm>
#include <iostream>
#include <numeric>
#include <random>
static std::vector<std::int64_t> reference(const WGraph& g,int start){
 int n=int(g.size());std::vector<std::vector<std::int64_t>>d(n,std::vector<std::int64_t>(n,INF));
 for(int i=0;i<n;++i){d[i][i]=0;for(auto e:g[i])d[i][e.to]=std::min(d[i][e.to],e.w);}
 for(int k=0;k<n;++k)for(int i=0;i<n;++i)if(d[i][k]!=INF)for(int j=0;j<n;++j)if(d[k][j]!=INF)d[i][j]=std::min(d[i][j],std::max(-INF/4,d[i][k]+d[k][j]));
 auto result=d[start];for(int k=0;k<n;++k)if(d[start][k]!=INF&&d[k][k]<0)for(int j=0;j<n;++j)if(d[k][j]!=INF)result[j]=-INF;return result;
}
int main(){std::mt19937 rng(20261026);int cases=0;
 for(int trial=0;trial<1200;++trial){int n=65+int(rng()%40);WGraph g(n);std::vector<int>pot(n);for(auto&x:pot)x=int(rng()%2001)-1000;
  for(int u=0;u<n;++u)for(int j=0;j<4+trial%5;++j){int to=int(rng()%n);if(to==u)to=(to+1)%n;auto w=std::int64_t(int(rng()%21)-10);
   if(trial%3==0)w=std::int64_t(rng()%2)+pot[to]-pot[u];if(trial%3==1&&u>=to)continue;g[u].emplace_back(to,w);}
  int start=int(rng()%n);auto expected=reference(g,start);std::vector<std::int64_t>d{123,456};bool expected_negative=std::find(expected.begin(),expected.end(),-INF)!=expected.end();
  if(SPFA(g,d,start)!=expected_negative||d!=expected)throw std::runtime_error("public mismatch");
  if(reinsirk::detail::SPFARun<false,false>(g,d,start)!=expected_negative||d!=expected)throw std::runtime_error("unbounded mismatch");++cases;
 }
 for(int count:{64,128,1024}){WGraph g(count+2);g[0].emplace_back(1,0);for(int i=1;i<=count;++i)g[0].emplace_back(i+1,count+1-i);for(int i=1;i<=count;++i)g[1].emplace_back(i+1,count);for(int i=1;i<=count;++i){g[i+1].emplace_back(1,0);if(i>=2)g[i+1].emplace_back(i,0);}std::vector<std::int64_t>expected(count+2,1),d;expected[0]=expected[1]=0;if(count<=128&&reference(g,0)!=expected)throw std::runtime_error("counter oracle");if(SPFA(g,d,0)||d!=expected)throw std::runtime_error("counter public");if(reinsirk::detail::SPFARun<false,false>(g,d,0)||d!=expected)throw std::runtime_error("counter unbounded");++cases;}
#ifndef SKIP_RUNTIME_CHECKS
 for(int kind=0;kind<4;++kind){int n=96;WGraph g(n);for(int i=0;i<80;++i){g[i].emplace_back((i+1)%80,-1);g[i].emplace_back((i+2)%80,0);}g[79].emplace_back(80,0);for(int i=80;i<94;++i)g[i].emplace_back(i+1,0);g[94].emplace_back(kind==0?-1:kind==1?n:95,kind==2?-1000000001:kind==3?1000000001:0);
  std::vector<std::int64_t>d{123,456};bool threw=false;try{SPFA(g,d,0);}catch(const std::out_of_range&){threw=true;}if(!threw||d!=std::vector<std::int64_t>({123,456}))throw std::runtime_error("checked output changed");++cases;}
#endif
 std::cout<<"cases "<<cases<<" PASS\n";
}

