from pathlib import Path
import hashlib
root=Path('/home/reinsirk/Atcoder_Env');base=Path(__file__).resolve().parent
bf=(root/'Graph/Bellman-Ford.cpp').read_text();a=bf.index('// 遅い反復だけを到達部分の強連結成分ごとに解く。');e=bf.index('// 反復1回の仕事量が大きい場合だけ成分分解を再試行する。',a)
helper=bf[a:e].replace('BellmanFordComponents','SPFAComponents').replace('BellmanFord:','SPFA:')
wrapper='''// 通常のFIFO処理が長引いた場合だけ、温存した距離から残りを解く。
template <bool Bounded>
#if defined(__GNUC__) || defined(__clang__)
[[gnu::noinline]]
#endif
inline void SPFAFinishComponents(const WGraph& graph,
    std::vector<std::int64_t>& distance, std::int64_t unreachable,
    std::vector<int>& affected, std::vector<std::uint8_t>& state) {
    const auto lower_bound = -static_cast<std::int64_t>(graph.size()) * 1'000'000'000;
    for (const int vertex : affected) distance[vertex] = lower_bound;
    std::vector<int> sources;
    sources.reserve(graph.size());
#ifndef SKIP_RUNTIME_CHECKS
    std::vector<std::uint8_t> checked(graph.size());
#endif
    for (std::size_t vertex = 0; vertex < graph.size(); ++vertex) {
        if (!graph[vertex].empty()) sources.push_back(static_cast<int>(vertex));
#ifndef SKIP_RUNTIME_CHECKS
        checked[vertex] = (state[vertex] & 2) != 0;
#endif
    }
    SPFAComponents(graph, sources, distance, unreachable, lower_bound, affected
#ifndef SKIP_RUNTIME_CHECKS
        , checked
#endif
    );
    for (const int vertex : affected) {
        state[vertex] |= 4;
        distance[vertex] = -INF;
    }
    (void)Bounded;
}
'''
s=(base/'baseline.hpp').read_text()
s=s.replace('#include <array>','#include <algorithm>\n#include <array>\n#include <span>',1)
anchor='// 64頂点以下はキュー・補助状態をスタックに置く。'
assert s.count(anchor)==1
s=s.replace(anchor,'#ifndef SIRKIT_SPFA_COMPONENTS_DEFINED\n#define SIRKIT_SPFA_COMPONENTS_DEFINED\nnamespace reinsirk::detail {\n'+helper+wrapper+'} // namespace reinsirk::detail\n#endif\n\n'+anchor,1)
s=s.replace('    std::int64_t current_distance = 0;','    std::size_t component_budget = graph.size();\n    unsigned component_rounds = 8;\n    std::int64_t current_distance = 0;',1)
anchor='        if (vertex_state & negative_bit)\n            continue;\n'
assert s.count(anchor)==1
s=s.replace(anchor,anchor+'''        if constexpr (!Small) {
            if (component_budget == 0) {
                if (--component_rounds == 0) {
                    SPFAFinishComponents<Bounded>(graph, distance, unreachable, affected, state);
                    break;
                }
                component_budget = graph.size();
            }
            --component_budget;
        }
''',1)
(base/'scc8.hpp').write_text(s)
print('frozen scc8.hpp bytes',len(s.encode()),'sha256',hashlib.sha256(s.encode()).hexdigest())

