// SPDX-License-Identifier: CC0-1.0
// SCC切替・長い追跡・非負成分で、全確保位置の失敗・出力保証・解放を確認する。
#ifndef SIRKIT_TEST_NEGATIVE_PATH_SOURCE
#define SIRKIT_TEST_NEGATIVE_PATH_SOURCE "../../../Graph/Bellman-Ford.cpp"
#endif
#include SIRKIT_TEST_NEGATIVE_PATH_SOURCE
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <limits>
#include <memory>
#include <new>
#include <stdexcept>
#include <vector>

static bool SPFAForcedUnbounded(const WGraph& graph, std::vector<std::int64_t>& d, int s){return reinsirk::detail::SPFARun<false,false>(graph,d,s);}

namespace {
std::int64_t allocation_budget = -1;
std::size_t live_allocations = 0, live_bytes = 0;
std::uint64_t allocation_calls = 0;
struct AllocationHeader { void* raw; std::size_t bytes; };

void* allocate_test(std::size_t bytes, std::size_t alignment) {
    ++allocation_calls;
    if (allocation_budget == 0) throw std::bad_alloc();
    if (allocation_budget > 0) --allocation_budget;
    alignment = std::max(alignment, alignof(std::max_align_t));
    const auto maximum = std::numeric_limits<std::size_t>::max();
    if (alignment > maximum - sizeof(AllocationHeader)) throw std::bad_alloc();
    const auto extra = sizeof(AllocationHeader) + alignment - 1;
    const auto requested = std::max(bytes, std::size_t{1});
    if (requested > maximum - extra) throw std::bad_alloc();
    void* raw = std::malloc(requested + extra);
    if (!raw) throw std::bad_alloc();
    void* cursor = static_cast<std::byte*>(raw) + sizeof(AllocationHeader);
    auto space = requested + alignment - 1;
    void* pointer = std::align(alignment, requested, cursor, space);
    if (!pointer) { std::free(raw); throw std::bad_alloc(); }
    auto* header = static_cast<AllocationHeader*>(pointer) - 1;
    header->raw = raw; header->bytes = bytes;
    ++live_allocations; live_bytes += bytes;
    return pointer;
}
void free_test(void* pointer) noexcept {
    if (!pointer) return;
    auto* header = static_cast<AllocationHeader*>(pointer) - 1;
    --live_allocations; live_bytes -= header->bytes;
    std::free(header->raw);
}
void require(bool condition) {
    if (!condition) throw std::runtime_error("Bellman-Ford SCC allocation check failed");
}
std::uint64_t fingerprint(const WGraph& graph) {
    std::uint64_t value = graph.size();
    for (const auto& row : graph) {
        value = value * 1000003 + row.size();
        for (const auto& edge : row)
            value = (value ^ static_cast<std::uint64_t>(edge.to)) * 1000033 + static_cast<std::uint64_t>(edge.w);
    }
    return value;
}
struct Statistics { std::size_t failures = 0; std::uint64_t allocations = 0; };
struct Work {
    std::vector<std::int64_t> distance;
    std::vector<int> sources, negative;
    bool negative_result = false;
#ifndef SKIP_RUNTIME_CHECKS
    std::vector<std::uint8_t> checked;
#endif
    Work(int n, bool direct) : distance(direct ? std::size_t(n) : 2, direct ? INF : 321) {
        if (!direct) { distance[1] = 654; return; }
        distance[0] = 0;
        for (int i = 0; i < n; ++i) sources.push_back(i);
#ifndef SKIP_RUNTIME_CHECKS
        checked.assign(std::size_t(n), 0);
#endif
    }
};
template<bool Direct> void invoke(const WGraph& graph, Work& work) {
    if constexpr (Direct) {
        reinsirk::detail::SPFAComponents(graph, work.sources, work.distance, INF,
            -static_cast<std::int64_t>(graph.size()) * 1'000'000'000, work.negative
#ifndef SKIP_RUNTIME_CHECKS
            , work.checked
#endif
        );
    } else work.negative_result = SPFAForcedUnbounded(graph, work.distance, 0);
}
template<bool Direct> void check_result(const WGraph& graph, const Work& work,
                                      const std::vector<std::int64_t>& expected) {
    const auto lower = -static_cast<std::int64_t>(graph.size()) * 1'000'000'000;
    require(work.distance.size() == graph.size());
    for (std::size_t i = 0; i < expected.size(); ++i)
        require(work.distance[i] == (Direct && expected[i] == -INF ? lower : expected[i]));
    if constexpr (!Direct)
        require(work.negative_result == (std::find(expected.begin(), expected.end(), -INF) != expected.end()));
}
template<bool Direct> Statistics inject(const WGraph& graph, const std::vector<std::int64_t>& expected) {
    const auto n = static_cast<int>(graph.size());
    const auto graph_hash = fingerprint(graph);
    const auto initial_live = live_allocations, initial_bytes = live_bytes;
    Statistics result;
    bool finished = false;
    for (std::int64_t budget = 0; budget < 1024 && !finished; ++budget) {
        {
            Work work(n, Direct);
            const auto calls_before = allocation_calls;
            bool failed = false;
            allocation_budget = budget;
            try { invoke<Direct>(graph, work); }
            catch (const std::bad_alloc&) { failed = true; }
            allocation_budget = -1;
            if (failed) {
                ++result.failures;
#ifndef SKIP_RUNTIME_CHECKS
                if constexpr (!Direct)
                    require(work.distance == std::vector<std::int64_t>({321, 654}));
#endif
                // 公開APIは同じ出力配列で再試行。内部ヘルパーは新しい作業状態で再試行する。
                if constexpr (!Direct) { invoke<Direct>(graph, work); check_result<Direct>(graph, work, expected); }
                else { Work retry(n, true); invoke<Direct>(graph, retry); check_result<Direct>(graph, retry, expected); }
            } else {
                result.allocations = allocation_calls - calls_before;
                require(result.allocations == static_cast<std::uint64_t>(budget));
                check_result<Direct>(graph, work, expected);
                finished = true;
            }
        }
        require(fingerprint(graph) == graph_hash);
        require(live_allocations == initial_live && live_bytes == initial_bytes);
    }
    require(finished && result.failures > 0);
    require(result.failures == result.allocations);
    return result;
}
} // namespace

void* operator new(std::size_t n) { return allocate_test(n, alignof(std::max_align_t)); }
void* operator new[](std::size_t n) { return allocate_test(n, alignof(std::max_align_t)); }
void* operator new(std::size_t n, std::align_val_t a) { return allocate_test(n, static_cast<std::size_t>(a)); }
void* operator new[](std::size_t n, std::align_val_t a) { return allocate_test(n, static_cast<std::size_t>(a)); }
void* operator new(std::size_t n, const std::nothrow_t&) noexcept { try { return allocate_test(n, alignof(std::max_align_t)); } catch (...) { return nullptr; } }
void* operator new[](std::size_t n, const std::nothrow_t&) noexcept { try { return allocate_test(n, alignof(std::max_align_t)); } catch (...) { return nullptr; } }
void* operator new(std::size_t n, std::align_val_t a, const std::nothrow_t&) noexcept { try { return allocate_test(n, static_cast<std::size_t>(a)); } catch (...) { return nullptr; } }
void* operator new[](std::size_t n, std::align_val_t a, const std::nothrow_t&) noexcept { try { return allocate_test(n, static_cast<std::size_t>(a)); } catch (...) { return nullptr; } }
void operator delete(void* p) noexcept { free_test(p); }
void operator delete[](void* p) noexcept { free_test(p); }
void operator delete(void* p, std::size_t) noexcept { free_test(p); }
void operator delete[](void* p, std::size_t) noexcept { free_test(p); }
void operator delete(void* p, std::align_val_t) noexcept { free_test(p); }
void operator delete[](void* p, std::align_val_t) noexcept { free_test(p); }
void operator delete(void* p, std::size_t, std::align_val_t) noexcept { free_test(p); }
void operator delete[](void* p, std::size_t, std::align_val_t) noexcept { free_test(p); }
void operator delete(void* p, const std::nothrow_t&) noexcept { free_test(p); }
void operator delete[](void* p, const std::nothrow_t&) noexcept { free_test(p); }
void operator delete(void* p, std::align_val_t, const std::nothrow_t&) noexcept { free_test(p); }
void operator delete[](void* p, std::align_val_t, const std::nothrow_t&) noexcept { free_test(p); }

int main() {
    const auto initial_live = live_allocations, initial_bytes = live_bytes;
    Statistics public_total, direct_total;
    std::size_t graphs = 0;
    const auto run_graph = [&](const WGraph& graph, const std::vector<std::int64_t>& expected) {
        const auto public_result = inject<false>(graph, expected), direct_result = inject<true>(graph, expected);
        public_total.failures += public_result.failures; public_total.allocations += public_result.allocations;
        direct_total.failures += direct_result.failures; direct_total.allocations += direct_result.allocations;
        ++graphs;
    };
    for (const int n : {65, 127, 257}) for (int kind = 0; kind < (n == 257 ? 3 : 2); ++kind) {
        WGraph graph(static_cast<std::size_t>(n));
        for (int i = 1; i < n; ++i) graph[0].emplace_back(i, 0);
        if (kind != 1)
            for (int i = 0; i < n; ++i) graph[i].emplace_back((i + 1) % n, -1);
        // 全頂点の負自己辺は、frontierの閾値を持つSCC切替でも毎パス全頂点を更新する。
        if (kind != 0)
            for (int i = 0; i < n; ++i) graph[i].emplace_back(i, -1);
        if (kind == 2)
            for (int i = 0; i < n; ++i) for (int j = 1; j <= 3; ++j)
                graph[i].emplace_back((i * 17 + j * 31) % n, (i + j) % 7);
        run_graph(graph, std::vector<std::int64_t>(graph.size(), -INF));
    }
    {
        constexpr int count = 64; WGraph graph(2 * count + 2); graph[0].emplace_back(1, 0);
        for (int i = 0; i < count; ++i) graph[1].emplace_back(i + 2, 1);
        for (int i = 0; i < count; ++i) graph[1].emplace_back(i + count + 2, 0);
        for (int i = 0; i < count; ++i) {
            graph[i + 2].emplace_back(1, 0); graph[i + count + 2].emplace_back(i + 2, -1);
        }
        std::vector<std::int64_t> expected(graph.size(), -INF); expected[0] = 0;
        run_graph(graph, expected);
    }
    {
        constexpr int size = 128; WGraph graph(size + 1);
        for (int i = size; i >= 1; --i) graph[0].emplace_back(i, size + 1 - i);
        for (int i = 1; i <= size; ++i) graph[i].emplace_back(i == 1 ? size : i - 1, 0);
        graph[size].emplace_back(size - 1, 0);
        std::vector<std::int64_t> expected(graph.size(), 1); expected[0] = 0;
        run_graph(graph, expected);
    }
    {
        constexpr int count = 128; WGraph graph(count + 2); graph[0].emplace_back(1, 0);
        for (int i = 1; i <= count; ++i) graph[0].emplace_back(i + 1, count + 1 - i);
        for (int i = 1; i <= count; ++i) graph[1].emplace_back(i + 1, count);
        for (int i = 1; i <= count; ++i) {
            graph[i + 1].emplace_back(1, 0); if (i >= 2) graph[i + 1].emplace_back(i, 0);
        }
        std::vector<std::int64_t> expected(graph.size(), 1); expected[0] = expected[1] = 0;
        run_graph(graph, expected);
    }
    {
        constexpr int size = 128, count = 64, center = size + 1, entry = size + 2 * count + 2, delay = entry + 1;
        WGraph graph(delay + 1);
        for (int i = size; i >= 1; --i) graph[0].emplace_back(i, size + 1 - i);
        for (int i = 1; i <= size; ++i) graph[i].emplace_back(i == 1 ? size : i - 1, 0);
        graph[size].emplace_back(size - 1, 0); graph[0].emplace_back(delay, 0);
        graph[delay].emplace_back(entry, 0); graph[entry].emplace_back(center, 0);
        for (int i = 0; i < count; ++i) graph[center].emplace_back(size + 2 + i, 1);
        for (int i = 0; i < count; ++i) graph[center].emplace_back(size + count + 2 + i, 0);
        for (int i = 0; i < count; ++i) {
            graph[size + 2 + i].emplace_back(center, 0); graph[size + count + 2 + i].emplace_back(size + 2 + i, -1);
        }
        std::vector<std::int64_t> expected(graph.size(), -INF); expected[0] = expected[entry] = expected[delay] = 0;
        for (int i = 1; i <= size; ++i) expected[i] = 1;
        run_graph(graph, expected);
    }
    require(live_allocations == initial_live && live_bytes == initial_bytes);
    std::cout << "{\"graphs\":" << graphs << ",\"public_injected_failures\":" << public_total.failures
              << ",\"helper_injected_failures\":" << direct_total.failures
              << ",\"successful_public_allocations\":" << public_total.allocations
              << ",\"successful_helper_allocations\":" << direct_total.allocations
              << ",\"retained_allocation_delta\":0,\"retained_byte_delta\":0}\n";
}

local_and_scc.scc8_unbounded_components_reference.cpp:
// SPDX-License-Identifier: CC0-1.0
// SCC処理・warm距離・DFS祖先判定を独立Floyd参照と照合する。
#ifndef SIRKIT_TEST_NEGATIVE_PATH_SOURCE
#define SIRKIT_TEST_NEGATIVE_PATH_SOURCE "../../../Graph/Bellman-Ford.cpp"
#endif
#include SIRKIT_TEST_NEGATIVE_PATH_SOURCE
#include <cassert>
#include <iostream>
#include <numeric>
#include <random>
#include <string>

static bool SPFAForcedUnbounded(const WGraph& graph, std::vector<std::int64_t>& d, int s){return reinsirk::detail::SPFARun<false,false>(graph,d,s);}
static std::uint64_t checks=0,cases=0;
static void require(bool condition){++checks;if(!condition)throw std::runtime_error("SCC independent review mismatch");}
static std::vector<std::int64_t> reference(const WGraph& g,int source){
    int n=int(g.size());std::vector<std::vector<std::int64_t>> d(n,std::vector<std::int64_t>(n,INF));
    for(int i=0;i<n;++i){d[i][i]=0;for(const auto&e:g[i])d[i][e.to]=std::min(d[i][e.to],e.w);}
    for(int k=0;k<n;++k)for(int i=0;i<n;++i)if(d[i][k]!=INF)for(int j=0;j<n;++j)if(d[k][j]!=INF)
        d[i][j]=std::min(d[i][j],std::max(-INF/4,d[i][k]+d[k][j]));
    auto result=d[source];
    for(int k=0;k<n;++k)if(d[source][k]!=INF&&d[k][k]<0)for(int j=0;j<n;++j)if(d[k][j]!=INF)result[j]=-INF;
    return result;
}
static void test(const WGraph&g,int source,int warm,const std::vector<std::int64_t>*known=nullptr){
    ++cases;const int n=int(g.size());auto expected=known?*known:reference(g,source);
    const std::int64_t lower=-std::int64_t(n)*1'000'000'000;
    std::vector<std::int64_t> distance(n,INF);distance[source]=0;
    for(int pass=0;pass<warm;++pass)for(int u=0;u<n;++u)if(distance[u]!=INF)
        for(const auto&e:g[u])distance[e.to]=std::min(distance[e.to],distance[u]+e.w);
    std::vector<int> sources,negative;
    for(int i=0;i<n;++i)if(!g[i].empty())sources.push_back(i);
#ifndef SKIP_RUNTIME_CHECKS
    std::vector<std::uint8_t> checked(n,0);
#endif
    reinsirk::detail::SPFAComponents(g,sources,distance,INF,lower,negative
#ifndef SKIP_RUNTIME_CHECKS
        ,checked
#endif
    );
    for(auto&d:distance)if(d==lower)d=-INF;
    require(distance==expected);
    std::vector<std::int64_t> actual{777,888};bool found=SPFAForcedUnbounded(g,actual,source);
    require(actual==expected);require(found==(std::find(expected.begin(),expected.end(),-INF)!=expected.end()));
}
int main(){
    std::mt19937 rng(20261025);
    for(int trial=0;trial<1500;++trial){
        int n=1+int(rng()%85);WGraph g(n);std::vector<int> potential(n);
        for(auto&x:potential)x=int(rng()%101)-50;
        for(int e=0,m=int(rng()%(5*n+1));e<m;++e){int u=int(rng()%n),v=int(rng()%n);
            std::int64_t w=int(rng()%21)-10;
            if(trial%3==0)w=int(rng()%11)+potential[v]-potential[u];
            if(trial%3==1&&u>=v)continue;
            g[u].emplace_back(v,w);
        }
        test(g,int(rng()%n),int(rng()%20));
    }
    // A ring with arbitrary warm entry points: two rounds must settle all entries.
    for(int size:{1,2,3,16,65,127})for(int kind:{0,1,2,3}){
        WGraph g(size+2);const int start=size,sink=size+1;
        for(int i=0;i<size;++i){const std::int64_t w=i==0?-std::int64_t(size-1)*7:7;
            g[i].emplace_back((i+1)%size,w+(kind==0&&i==0?-1:kind==1&&i==0?1:0));
            if(kind==3)g[i].emplace_back(sink,100);
            g[start].emplace_back(i,std::int64_t(rng()%1000));
        }
        test(g,start,0);test(g,start,17);
    }
    // Stack-safe Tarjan, negative terminal SCC, and backward topological numbering.
    for(int n:{65,20000}){
        WGraph g(n);for(int i=1;i<n;++i)g[i].emplace_back(i-1,-1);
        std::vector<std::int64_t> expected(n);for(int i=0;i<n;++i)expected[i]=-std::int64_t(n-1-i);
        test(g,n-1,0,&expected);
        g[n/2].emplace_back(n/2,-1);for(int i=0;i<=n/2;++i)expected[i]=-INF;
        test(g,n-1,0,&expected);
    }
    // Aを先にDFSで完了させ、B→Aの交差辺で負閉路を作る。木の祖先辺だけでは見つからない。
    for(int k:{1,2,3,8,32,64,128,1249})for(bool nonnegative:{false,true}){
        const int n=2*k+2;WGraph g(n);g[0].emplace_back(1,0);
        for(int i=0;i<k;++i)g[1].emplace_back(i+2,1);
        for(int i=0;i<k;++i)g[1].emplace_back(i+k+2,0);
        for(int i=0;i<k;++i){g[i+2].emplace_back(1,nonnegative?1:0);g[i+k+2].emplace_back(i+2,-1);}
        // 中心→B→A→中心は-1/0。始点へ戻る辺はない。非負版のAの最短値は-1。
        std::vector<std::int64_t> expected(n,-INF);expected[0]=0;
        if(nonnegative){expected.assign(n,0);for(int i=0;i<k;++i)expected[i+2]=-1;}
        if(k<=64)require(reference(g,0)==expected);
        test(g,0,0,&expected);test(g,0,17,&expected);
    }
    // 成分内の有限距離が7/8/9/10パスで確定する。全閉路の換算重みは0。
    for(int gap:{7,8,9,10})for(bool shifted:{false,true}){
        constexpr int size=20;WGraph g(size+1);std::vector<std::int64_t> expected(size+1);
        if(shifted)for(int i=1;i<=size;++i)expected[i]=i%7-3;
        const auto add=[&](int from,int to){g[from].emplace_back(to,expected[to]-expected[from]);};
        add(0,1);for(int i=gap+1;i<=size;++i)add(0,i);
        for(int i=1;i<=size;++i)add(i,i==size?1:i+1);
        add(1,2); // 多重辺で単一閉路専用経路を避ける。
        require(reference(g,0)==expected);
        test(g,0,0,&expected);test(g,0,17,&expected);
    }
    // 負閉路なしでも、多数の厳密更新と前駆検査を要する逆向きの距離改善波。
    for(int size:{8,9,16,64,128,2499})for(bool shifted:{false,true}){
        WGraph g(size+1);std::vector<std::int64_t> potential(size+1),expected(size+1,1);
        if(shifted)for(int i=1;i<=size;++i)potential[i]=i%7-3;
        expected[0]=0;for(int i=1;i<=size;++i)expected[i]+=potential[i];
        for(int i=size;i>=1;--i)g[0].emplace_back(i,size+1-i+potential[i]);
        for(int i=1;i<=size;++i){const int to=i==1?size:i-1;g[i].emplace_back(to,potential[to]-potential[i]);}
        g[size].emplace_back(size-1,potential[size-1]-potential[size]);
        // 始点からsizeへ費用1で入り、換算重み0の閉路で全頂点へ到達する。
        if(size<=64)require(reference(g,0)==expected);
        test(g,0,0,&expected);test(g,0,17,&expected);
    }
    // 独立な負閉路群でfrontierを増やし、遅い非負成分も公開APIのSCC切替へ到達させる。
    for(int size:{64,128,2368}){
        constexpr int count=64;const int center=size+1,entry=size+2*count+2,delay=entry+1;
        WGraph g(delay+1);
        for(int i=size;i>=1;--i)g[0].emplace_back(i,size+1-i);
        for(int i=1;i<=size;++i)g[i].emplace_back(i==1?size:i-1,0);
        g[size].emplace_back(size-1,0);g[0].emplace_back(delay,0);
        g[delay].emplace_back(entry,0);g[entry].emplace_back(center,0);
        for(int i=0;i<count;++i)g[center].emplace_back(size+2+i,1);
        for(int i=0;i<count;++i)g[center].emplace_back(size+count+2+i,0);
        for(int i=0;i<count;++i){g[size+2+i].emplace_back(center,0);g[size+count+2+i].emplace_back(size+2+i,-1);}
        std::vector<std::int64_t> expected(g.size(),-INF);expected[0]=expected[entry]=expected[delay]=0;
        for(int i=1;i<=size;++i)expected[i]=1;
        if(size<=128)require(reference(g,0)==expected);
        test(g,0,0,&expected);test(g,0,17,&expected);
    }
    // 初期activeの逆順を常用すると遅くなる非負成分。元の順序なら1パスで確定する。
    for(int count:{8,9,64,128,1248})for(bool shifted:{false,true}){
        WGraph g(count+2);std::vector<std::int64_t> potential(g.size()),expected(g.size(),1);
        if(shifted)for(int i=1;i<int(g.size());++i)potential[i]=i%7-3;
        expected[0]=0;expected[1]=potential[1];
        for(int i=2;i<int(g.size());++i)expected[i]+=potential[i];
        const auto add=[&](int from,int to,std::int64_t cost){g[from].emplace_back(to,cost+potential[to]-potential[from]);};
        add(0,1,0);for(int i=1;i<=count;++i)add(0,i+1,count+1-i);
        for(int i=1;i<=count;++i)add(1,i+1,count);
        for(int i=1;i<=count;++i){add(i+1,1,0);if(i>=2)add(i+1,i,0);}
        if(count<=64)require(reference(g,0)==expected);
        test(g,0,0,&expected);test(g,0,17,&expected);
    }
    // 多数の負成分の下流を長鎖・終点まで伝播し、有限枝と未到達成分を保つ。
    for(int size:{160,1024})for(int permutation:{0,1,2}){
        WGraph g(size);std::vector<int> label(size);std::iota(label.begin(),label.end(),0);
        if(permutation==1)std::reverse(label.begin(),label.end());
        if(permutation==2)std::shuffle(label.begin(),label.end(),rng);
        const auto add=[&](int from,int to,std::int64_t weight){g[label[from]].emplace_back(label[to],weight);};
        std::vector<std::int64_t> expected(size,-INF);
        expected[label[0]]=0;expected[label[size-3]]=7;expected[label[size-2]]=12;expected[label[size-1]]=INF;
        for(int i=1;i<=64;++i){add(0,i,i%3);add(i,i,-1);add(i,size-4,0);}
        for(int i=size-4;i>65;--i)add(i,i-1,0);
        add(0,size-3,7);add(size-3,size-2,5);add(size-1,size-1,-1);
        if(size==160)require(reference(g,label[0])==expected);
        test(g,label[0],0,&expected);test(g,label[0],17,&expected);
    }
    // Tarjanのactive内に残っていても、DFS祖先でない頂点への辺は閉路証拠にしない。
    {
        WGraph g(3);g[0].emplace_back(1,100);g[1].emplace_back(0,0);
        g[0].emplace_back(2,0);g[2].emplace_back(1,0);
        test(g,0,0);test(g,0,17);
    }
#ifndef SKIP_RUNTIME_CHECKS
    // Existing lower-bound seeds can precede SCC dispatch; their unseen descendants still need validation.
    for(int kind=0;kind<4;++kind){
        const int n=80;WGraph g(n);for(int j=0;j<=n;++j)g[0].emplace_back(0,-1'000'000'000);
        g[0].emplace_back(n-2,0);for(int i=n-2;i>1;--i)g[i].emplace_back(i-1,0);
        g[1].emplace_back(kind==0?-1:kind==1?n:0,kind==2?-1'000'000'001:kind==3?1'000'000'001:0);
        // An unreachable invalid edge must not be inspected.
        g[n-1].emplace_back(n+10,1'000'000'001);
        std::vector<std::int64_t> d{123,456};bool threw=false;
        try{SPFAForcedUnbounded(g,d,0);}catch(const std::out_of_range&){threw=true;}
        require(threw);require(d==std::vector<std::int64_t>({123,456}));
        // SCC切替前から負影響が判明していても、下流の検査を省かない。
        std::vector<int> sources,negative{0};
        for(int i=0;i<n;++i)if(!g[i].empty())sources.push_back(i);
        const auto lower=-std::int64_t(n)*1'000'000'000;
        d.assign(n,INF);d[0]=lower;
        std::vector<std::uint8_t> checked(n,0);threw=false;
        try{reinsirk::detail::SPFAComponents(g,sources,d,INF,lower,negative,checked);}
        catch(const std::out_of_range&){threw=true;}
        require(threw);
    }
#endif
    {
        const int n=80;WGraph g(n);
        for(int j=0;j<=n;++j)g[0].emplace_back(0,-1'000'000'000);
        g[0].emplace_back(n-2,0);for(int i=n-2;i>1;--i)g[i].emplace_back(i-1,0);
        g[n-1].emplace_back(n+10,1'000'000'001);
        std::vector<std::int64_t> expected(n,-INF);expected[n-1]=INF;
        test(g,0,0,&expected);
    }
    std::cout<<"{\"cases\":"<<cases<<",\"checks\":"<<checks<<"}\n";
}

local_and_scc.scc_simple8-frozen.hpp:
// SPDX-License-Identifier: CC0-1.0
// 参考: https://zenn.dev/reputeless/books/standard-cpp-for-competitive-programming/viewer/bellman-ford
// ドキュメント: https://github.com/reinsirk/sirkit-cpp-library/blob/main/Document/negative_shortest_paths.md
//
// API一覧
// [共通型・定数]
// Edge(to,w): 行先toとint64_tの重みwを持つ有向辺。
// WGraph: 出発点を隣接リストの添字とする辺列。INF=std::int64_t{1}<<60。
//
// [SPFA]
// SPFA(graph, distances, start_index): 始点からの最短距離をdistancesに格納し、到達可能な負閉路があればtrueを返す。
// SKIP_RUNTIME_CHECKSを定義すると入力検査を省く。
// 検査は始点と処理中に参照する辺のみ。未到達成分は走査しない。
// 更新された頂点だけをFIFOキューで処理するSPFA。標準C++23、重みは[-1e9, 1e9]。
// 到達可能な負閉路があればtrue。距離は成功時に全上書きし、未到達INF・負影響-INF。
// 最悪O(VE+V+E)時間・O(V)追加領域。有限距離のINF/-INF衝突はoverflow_error。

#include <algorithm>
#include <array>
#include <span>
#include <type_traits>
#include <cstddef>
#include <cstdint>
#include <limits>
#include <memory>
#include <stdexcept>
#include <vector>

#ifndef SIRKIT_INF_DEFINED
#define SIRKIT_INF_DEFINED
inline constexpr std::int64_t INF = std::int64_t{1} << 60;
#endif

#ifndef SIRKIT_GRAPH_TYPES_DEFINED
#define SIRKIT_GRAPH_TYPES_DEFINED
struct Edge
{
    int to;
    std::int64_t w;
    Edge(int destination, std::int64_t weight) : to(destination), w(weight) {}
};
using WGraph = std::vector<std::vector<Edge>>;
#endif

#ifndef SIRKIT_SPFA_COMPONENTS_DEFINED
#define SIRKIT_SPFA_COMPONENTS_DEFINED
namespace reinsirk::detail {
// 遅い反復だけを到達部分の強連結成分ごとに解く。追加領域O(V)。
#if defined(__GNUC__) || defined(__clang__)
[[gnu::noinline]]
#endif
inline void SPFAComponents(const WGraph& graph, std::span<const int> sources,
    std::vector<std::int64_t>& distance, std::int64_t unreachable, std::int64_t lower_bound,
    std::vector<int>& negative
#ifndef SKIP_RUNTIME_CHECKS
    , std::vector<std::uint8_t>& checked
#endif
) {
#ifndef SKIP_RUNTIME_CHECKS
    const int n = static_cast<int>(graph.size());
#endif
    struct Frame { int vertex; std::size_t edge; };
    std::vector<int> order(graph.size(), -1), low(graph.size()), component(graph.size(), -1);
    std::vector<int> active, members;
    std::vector<std::int64_t> tree_distance(graph.size());
    // stateの下位bitは現在のDFS祖先、次のbitは負閉路の証拠。
    std::vector<std::uint8_t> state(graph.size(), 0), negative_component;
    std::vector<std::size_t> boundary{0};
    std::vector<Frame> dfs;
    int clock = 0;
    const auto discover = [&](int vertex, std::int64_t tree_value) {
        tree_distance[vertex] = tree_value;
        state[vertex] = 1;
        order[vertex] = low[vertex] = clock++;
        active.push_back(vertex);
        dfs.push_back({vertex, 0});
    };
    for (const int root : sources) {
        if (distance[root] == unreachable || order[root] >= 0) continue;
        discover(root, 0);
        while (!dfs.empty()) {
            auto& frame = dfs.back();
            const int from = frame.vertex;
            if (frame.edge != graph[from].size()) {
                const auto& edge = graph[from][frame.edge++];
#ifndef SKIP_RUNTIME_CHECKS
                if (!checked[from]) {
                    if (edge.to < 0 || edge.to >= n)
                        throw std::out_of_range("SPFA: invalid destination vertex");
                    if (edge.w < -1'000'000'000 || edge.w > 1'000'000'000)
                        throw std::out_of_range("SPFA: cost must be in [-1e9, 1e9]");
                }
#endif
                if (order[edge.to] < 0) discover(edge.to, tree_distance[from] + edge.w);
                else if (component[edge.to] < 0) {
                    low[from] = std::min(low[from], order[edge.to]);
                    // DFS木上の祖先へ戻る辺で、閉路の重みが負と確定する。
                    if ((state[edge.to] & 1) && tree_distance[from] + edge.w < tree_distance[edge.to])
                        state[from] |= 2;
                }
            } else {
                if (low[from] == order[from]) {
                    const int id = static_cast<int>(boundary.size() - 1);
                    bool found_negative = false;
                    for (;;) {
                        const int vertex = active.back(); active.pop_back();
                        component[vertex] = id;
                        found_negative |= (state[vertex] & 2) != 0;
                        members.push_back(vertex);
                        if (vertex == from) break;
                    }
                    boundary.push_back(members.size());
                    negative_component.push_back(found_negative);
                }
#ifndef SKIP_RUNTIME_CHECKS
                checked[from] = 1;
#endif
                state[from] &= 2;
                dfs.pop_back();
                if (!dfs.empty()) low[dfs.back().vertex] = std::min(low[dfs.back().vertex], low[from]);
            }
        }
    }
    const auto mark = [&](int vertex) {
        if (distance[vertex] != lower_bound) {
            negative.push_back(vertex);
            distance[vertex] = lower_bound;
        }
    };
    for (std::size_t block = boundary.size() - 1; block != 0; --block) {
        const int id = static_cast<int>(block - 1);
        const auto first = boundary[block - 1], last = boundary[block], size = last - first;
        bool affected = negative_component[id] != 0, ring = true;
        for (auto position = first; position != last; ++position) {
            const int from = members[position];
            affected |= distance[from] == lower_bound;
            if (graph[from].size() != 1 || component[graph[from].front().to] != id) ring = false;
        }
        if (!affected && ring) {
            int from = members[first];
            for (std::size_t step = 0; step < 2 * size; ++step) {
                const auto& edge = graph[from].front();
                if (distance[from] != unreachable)
                    distance[edge.to] = std::min(distance[edge.to], distance[from] + edge.w);
                from = edge.to;
            }
        } else if (!affected && size > 1) {
            std::vector<int> next;
            active.clear();
            for (auto position = first; position != last; ++position) {
                const int from = members[position];
                order[from] = distance[from] != unreachable;
                if (order[from]) active.push_back(from);
            }
            bool converged = false;
            for (std::size_t pass = 1; pass < std::min(size, std::size_t{8}); ++pass) {
                for (const int from : active) {
                    order[from] = 0;
                    for (const auto& edge : graph[from]) {
                        if (component[edge.to] != id) continue;
                        const auto candidate = distance[from] + edge.w;
                        if (candidate < distance[edge.to]) {
                            if (candidate <= lower_bound) { affected = true; break; }
                            distance[edge.to] = candidate;
                            if (!order[edge.to]) {
                                next.push_back(edge.to);
                                order[edge.to] = 1;
                            }
                        }
                    }
                    if (affected) break;
                }
                if (affected) break;
                if (next.empty()) { converged = true; break; }
                active.swap(next);
                next.clear();
            }
            if (!affected && !converged && size > 8) {
                // 少数回で収束する成分の順序は保ち、残りだけ反転する。
                std::reverse(active.begin(), active.end());
                // Tarjanで使い終えた配列を前駆頂点へ転用する。
                for (auto position = first; position != last; ++position) low[members[position]] = -1;
                std::size_t cycle_budget = size;
                for (std::size_t pass = 8; pass < size; ++pass) {
                    for (const int from : active) {
                        order[from] = 0;
                        for (const auto& edge : graph[from]) {
                            if (component[edge.to] != id) continue;
                            const auto candidate = distance[from] + edge.w;
                            if (candidate < distance[edge.to]) {
                                if (candidate <= lower_bound) { affected = true; break; }
                                distance[edge.to] = candidate;
                                low[edge.to] = from;
                                if (cycle_budget != 0) --cycle_budget;
                                if (!order[edge.to]) {
                                    next.push_back(edge.to);
                                    order[edge.to] = 1;
                                }
                            }
                        }
                        if (affected) break;
                    }
                    if (affected) break;
                    if (next.empty()) { converged = true; break; }
                    // 厳密な緩和で得た前駆閉路は負。検出費用は緩和回数に応じて抑える。
                    if (cycle_budget == 0) {
                        for (auto position = first; position != last; ++position) state[members[position]] = 0;
                        for (auto position = first; position != last; ++position) {
                            const int root = members[position];
                            int at = root;
                            while (low[at] >= 0 && state[at] == 0) { state[at] = 1; at = low[at]; }
                            if (low[at] >= 0 && state[at] == 1) { affected = true; break; }
                            at = root;
                            while (low[at] >= 0 && state[at] == 1) { state[at] = 2; at = low[at]; }
                        }
                        cycle_budget = size;
                        if (affected) break;
                    }
                    active.swap(next);
                    next.clear();
                }
            }
            if (!affected && !converged) {
                for (auto position = first; position != last; ++position) {
                    const int from = members[position];
                    if (distance[from] == unreachable) continue;
                    for (const auto& edge : graph[from])
                        if (component[edge.to] == id && distance[from] + edge.w < distance[edge.to]) affected = true;
                }
            }
        }
        if (affected)
            for (auto position = first; position != last; ++position) mark(members[position]);
        for (auto position = first; position != last; ++position) {
            const int from = members[position];
            if (distance[from] == unreachable) continue;
            for (const auto& edge : graph[from]) {
                if (component[edge.to] == id) continue;
                if (affected) mark(edge.to);
                else {
                    const auto candidate = distance[from] + edge.w;
                    if (candidate < distance[edge.to]) {
                        if (candidate <= lower_bound) mark(edge.to);
                        else distance[edge.to] = candidate;
                    }
                }
            }
        }
    }
}


// 通常のFIFO処理が長引いた場合だけ、温存した距離から残りを解く。
#if defined(__GNUC__) || defined(__clang__)
[[gnu::noinline, gnu::cold]]
#endif
inline void SPFAFinishComponents(const WGraph& graph,
    std::vector<std::int64_t>& distance, std::int64_t unreachable,
    std::vector<int>& affected, std::vector<std::uint8_t>& state) {
    const auto lower_bound = -static_cast<std::int64_t>(graph.size()) * 1'000'000'000;
    for (const int vertex : affected) distance[vertex] = lower_bound;
    std::vector<int> sources;
    sources.reserve(graph.size());
#ifndef SKIP_RUNTIME_CHECKS
    std::vector<std::uint8_t> checked(graph.size());
#endif
    for (std::size_t vertex = 0; vertex < graph.size(); ++vertex) {
        if (!graph[vertex].empty()) sources.push_back(static_cast<int>(vertex));
#ifndef SKIP_RUNTIME_CHECKS
        checked[vertex] = (state[vertex] & 2) != 0;
#endif
    }
    SPFAComponents(graph, sources, distance, unreachable, lower_bound, affected
#ifndef SKIP_RUNTIME_CHECKS
        , checked
#endif
    );
    for (const int vertex : affected) {
        state[vertex] |= 4;
        distance[vertex] = -INF;
    }
}
} // namespace reinsirk::detail
#endif

// 64頂点以下はキュー・補助状態をスタックに置く。
#ifndef SIRKIT_SPFA_DEFINED
#define SIRKIT_SPFA_DEFINED
namespace reinsirk::detail {
template <bool Small, bool Bounded>
inline bool SPFARun(const WGraph &graph, std::vector<std::int64_t> &distances,
                 int start_index)
{
    constexpr std::int64_t max_cost = 1'000'000'000;
    if (graph.size() > static_cast<std::size_t>(std::numeric_limits<int>::max()))
        throw std::length_error("SPFA: too many vertices");
    const int n = static_cast<int>(graph.size());
#ifndef SKIP_RUNTIME_CHECKS
    if (start_index < 0 || start_index >= n)
        throw std::out_of_range("SPFA: invalid start vertex");
#endif

    if (graph[start_index].empty()) {
#ifndef SKIP_RUNTIME_CHECKS
        std::vector<std::int64_t> result(graph.size(), INF);
        result[start_index] = 0;
        distances.swap(result);
#else
        distances.assign(graph.size(), INF);
        distances[start_index] = 0;
#endif
        return false;
    }

    // n*最大辺重み<INFなら、内部値と出力値の変換が要らない。
    const std::int64_t unreachable = Bounded ? INF : (static_cast<std::int64_t>(n) + 1) * max_cost;
    std::vector<std::int64_t> local_distance;
#ifndef SKIP_RUNTIME_CHECKS
    auto& distance = local_distance;
#else
    auto& distance = Small ? distances : local_distance;
#endif
    distance.assign(graph.size(), unreachable);
    std::conditional_t<Small, std::array<int, 64>, std::vector<int>> path_edges;
    if constexpr (Small) path_edges.fill(0);
    else path_edges.assign(graph.size(), 0);
    std::vector<int> affected;
    // stateのbit 0はキュー内、bit 1は初回検査済み、bit 2は負閉路の影響。
    constexpr std::uint8_t queued_bit = 1;
#ifndef SKIP_RUNTIME_CHECKS
    constexpr std::uint8_t checked_bit = 2;
#endif
    constexpr std::uint8_t negative_bit = 4;
    std::conditional_t<Small, std::array<std::uint8_t, 64>, std::vector<std::uint8_t>> state;
    if constexpr (Small) state.fill(0);
    else state.assign(graph.size(), 0);
    // 同時にキューに入る頂点はV個以下。書いた要素だけ読むため初期化は不要。
    const std::size_t queue_capacity = graph.size();
    std::array<int, Small ? 64 : 0> local_queue;
    std::unique_ptr<int[]> queue_owner;
    int* queue;
    if constexpr (Small) queue = local_queue.data();
    else {
        queue_owner = std::make_unique_for_overwrite<int[]>(queue_capacity);
        queue = queue_owner.get();
    }
    std::size_t head = 0, tail = 0, queued = 0;
    const auto enqueue = [&](int vertex)
    {
        queue[tail] = vertex;
        if (++tail == queue_capacity)
            tail = 0;
        ++queued;
    };
    distance[start_index] = 0;
    enqueue(start_index);
    state[start_index] = queued_bit;

    // 負閉路の下流を一度だけ走査し、以後は距離の緩和から除外する。
    const auto mark_negative = [&](int seed)
    {
        if ((state[seed] & negative_bit))
            return;
        // 負閉路が見つかるまでは、影響頂点の領域を確保しない。
        if (affected.empty())
            affected.reserve(graph.size());
        const std::size_t first = affected.size();
        state[seed] |= negative_bit;
        if constexpr (Bounded) distance[seed] = -INF;
        affected.push_back(seed);
        for (std::size_t affected_head = first; affected_head < affected.size(); ++affected_head)
        {
            for (const auto &edge : graph[affected[affected_head]])
            {
#ifndef SKIP_RUNTIME_CHECKS
                // 初回検査の途中から来る場合もあるため、伝播側でも検査する。
                if (edge.to < 0 || edge.to >= n)
                    throw std::out_of_range("SPFA: invalid destination vertex");
                if (edge.w < -max_cost || edge.w > max_cost)
                    throw std::out_of_range("SPFA: cost must be in [-1e9, 1e9]");
#endif
                if ((state[edge.to] & negative_bit))
                    continue;
                state[edge.to] |= negative_bit;
                if constexpr (Bounded) distance[edge.to] = -INF;
                affected.push_back(edge.to);
            }
        }
    };

    const auto budget_limit = std::numeric_limits<std::size_t>::max();
    std::size_t component_budget = graph.size() <= budget_limit / 8 ? graph.size() * 8 : budget_limit;
    std::int64_t current_distance = 0;
    int current_length = 0;
    // 通常はfromが負影響ならtrue。Directでは未キューの更新先、なければ-1。
#if defined(__clang__)
    const auto relax_edge = [&]<bool Single = false, bool Direct = false>(int from, const Edge &edge)
        -> std::conditional_t<Direct, int, bool>
#else
    const auto relax_edge = [&]<bool Single = false>(int from, const Edge &edge)
#endif
    {
#if defined(__clang__)
        constexpr std::conditional_t<Direct, int, bool> unchanged = Direct ? -1 : 0;
#else
        constexpr bool unchanged = false;
#endif
        // Boundedでは候補>-INFなので、負影響先は距離比較だけで除外できる。
        if constexpr (!Bounded) if (state[edge.to] & negative_bit)
            return unchanged;
        // 格納する経路はn辺未満なので、候補の加算もint64_t内に収まる。
        const std::int64_t candidate = current_distance + edge.w;
        if (candidate >= distance[edge.to])
            return unchanged;
        const int length = current_length;
        // 複数辺では負自己ループを即時に処理し、保持した始点距離を使い続けない。
        if (length >= n || (!Single && edge.to == from)) [[unlikely]]
        {
            mark_negative(edge.to);
#if defined(__clang__)
            if constexpr (!Direct) if (state[from] & negative_bit)
                return true;
#else
            if ((state[from] & negative_bit))
                return true;
#endif
            return unchanged;
        }
        distance[edge.to] = candidate;
        path_edges[edge.to] = length;
        if (!(state[edge.to] & queued_bit))
        {
#if defined(__clang__)
            if constexpr (Direct) return edge.to;
            else
#endif
            {
                enqueue(edge.to);
                state[edge.to] |= queued_bit;
            }
        }
        return unchanged;
    };

    while (queued != 0)
    {
#if defined(__clang__)
        std::conditional_t<Small, const int, int> from = queue[head];
#else
        const int from = queue[head];
#endif
        if (++head == queue_capacity)
            head = 0;
        --queued;
#if defined(__clang__)
    process_vertex:
#endif
        const std::uint8_t vertex_state = state[from];
        if (vertex_state & negative_bit)
            continue;
        if constexpr (!Small) {
            if (component_budget == 0) [[unlikely]] {
                SPFAFinishComponents(graph, distance, unreachable, affected, state);
                break;
            }
            --component_budget;
        }
#ifndef SKIP_RUNTIME_CHECKS
        state[from] = checked_bit;
#else
        state[from] = 0;
#endif
        current_distance = distance[from];
        current_length = path_edges[from] + 1;
#ifndef SKIP_RUNTIME_CHECKS
        const bool validate = !(vertex_state & checked_bit);
#endif
        // 1辺ならループと途中の自己辺更新への対処を省ける。
        if (graph[from].size() == 1) {
            const auto& edge = graph[from].front();
#ifndef SKIP_RUNTIME_CHECKS
            if (validate) {
                if (edge.to < 0 || edge.to >= n)
                    throw std::out_of_range("SPFA: invalid destination vertex");
                if (edge.w < -max_cost || edge.w > max_cost)
                    throw std::out_of_range("SPFA: cost must be in [-1e9, 1e9]");
            }
#endif
#if defined(__clang__)
            // 待機頂点がなければ直接進む。小規模は従来のコードを保つ。
            if constexpr (!Small) {
                if (queued == 0) {
                    const int next = relax_edge.template operator()<true, true>(from,edge);
                    if (next >= 0) {
                        from = next;
                        goto process_vertex;
                    }
                } else relax_edge.template operator()<true>(from,edge);
            } else
#endif
            relax_edge.template operator()<true>(from,edge);
            continue;
        }
#ifndef SKIP_RUNTIME_CHECKS
        if (validate)
        {
            for (const auto &edge : graph[from])
            {
                if (edge.to < 0 || edge.to >= n)
                    throw std::out_of_range("SPFA: invalid destination vertex");
                if (edge.w < -max_cost || edge.w > max_cost)
                    throw std::out_of_range("SPFA: cost must be in [-1e9, 1e9]");
                if (relax_edge(from, edge))
                    break;
            }
        }
        else
#endif
        {
            for (const auto &edge : graph[from])
                if (relax_edge(from, edge))
                    break;
        }
    }

    if constexpr (!Bounded) for (int vertex = 0; vertex < n; ++vertex)
    {
        if ((state[vertex] & negative_bit))
            distance[vertex] = -INF;
        else if (distance[vertex] == unreachable)
            distance[vertex] = INF;
        else if (distance[vertex] <= -INF || distance[vertex] >= INF)
            throw std::overflow_error("SPFA: finite distance collides with INF/-INF");
    }
#ifndef SKIP_RUNTIME_CHECKS
    distances.swap(distance);
#else
    if constexpr (!Small) distances.swap(distance);
#endif
    return !affected.empty();
}
} // namespace reinsirk::detail

inline bool SPFA(const WGraph& graph, std::vector<std::int64_t>& distances, int start_index) {
    if (graph.size() <= 64) return reinsirk::detail::SPFARun<true, true>(graph, distances, start_index);
    if (graph.size() <= static_cast<std::size_t>((INF - 1) / 1'000'000'000))
        return reinsirk::detail::SPFARun<false, true>(graph, distances, start_index);
    return reinsirk::detail::SPFARun<false, false>(graph, distances, start_index);
}
#endif

