   if to not in seen:seen.add(to);todo.append(to)
 assert n-1 in seen,f['name']
for skip in [False,True]:
 s=(root/'Verify/current/submissions/spfa.cpp').read_text()
 if not skip:s=s.replace('#define SKIP_RUNTIME_CHECKS\n','',1)
 (base/('skip.cpp'if skip else'checked.cpp')).write_text(s)
(base/'shared.cpp').write_text(''.join('#include "'+str(root/p)+'"\n' for p in ['Graph/Bellman-Ford_SFPA.cpp','Graph/Bellman-Ford.cpp','Graph/Bellman-Ford_SFPA.cpp'])+'int main(){WGraph g(1);std::vector<std::int64_t>a,b;return SPFA(g,a,0)||BellmanFord(g,b,0)||a!=b;}\n')
