   exe=base/(cfg+'-'+kind);cmd=['taskset','-c','8',*cc,'-std=c++23','-O2','-Wall','-Wextra','-pedantic',*flags,str(source),'-o',str(exe)]
   p=subprocess.run(cmd,capture_output=True,timeout=180);assert p.returncode==0,p.stderr.decode()
   entry={'config':cfg,'kind':kind,'command':cmd,'compile_diagnostics':p.stderr.decode(),'exit':0}
